#!/usr/bin/env bash
# Session-layer runner for remote execution environments (cloud VMs) only.
# Shared part generated by the remote-setup skill — do not edit this file by hand (overwritten when the skill runs again).
# Repository-specific steps go in steps.sh; VM provisioning (heavy installs) goes in environment-setup.sh.
#
# Started by: the SessionStart hook in .claude/settings.json (every session).
# Manual retry also works: bash scripts/remote-setup/setup.sh
set -u

# ---- Remote gate: exit immediately with no output when local ----
is_remote() {
  # Official cloud environment flag (primary check; true only on Anthropic-managed remote infrastructure)
  [ "${CLAUDE_CODE_REMOTE:-}" = "true" ] && return 0
  # Unofficial secondary check based on observed values (remote_cowork / remote_desktop, etc.)
  case "${CLAUDE_CODE_ENTRYPOINT:-}" in remote_*) return 0 ;; esac
  # Explicit override: adapters for cloud sandboxes such as Codex / Cursor
  # call it with REMOTE_SETUP_FORCE=1 (from their own cloud-only mechanism).
  # Also usable for local testing, but note that real installs will run.
  [ "${REMOTE_SETUP_FORCE:-}" = "1" ] && return 0
  return 1
}
is_remote || exit 0

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
REPO_NAME="$(basename "$REPO_ROOT")"

STATE_DIR="${HOME}/.cache/remote-setup"
mkdir -p "$STATE_DIR"
LOG_FILE="$STATE_DIR/${REPO_NAME}.log"
STAMP_FILE="$STATE_DIR/${REPO_NAME}.stamp"

log() { printf '%s %s\n' "$(date -u +%FT%TZ)" "$*" >>"$LOG_FILE"; }
# stdout is injected into the session's context via the SessionStart hook — keep it short
say() { echo "[remote-setup] $*"; log "$*"; }

# shellcheck source=steps.sh
. "$SCRIPT_DIR/steps.sh"

steps_hash() { sha256sum "$SCRIPT_DIR/steps.sh" | cut -d' ' -f1; }

check_env_vars() {
  local v missing=()
  for v in ${REQUIRED_ENV_VARS[@]+"${REQUIRED_ENV_VARS[@]}"}; do
    [ -z "${!v:-}" ] && missing+=("$v")
  done
  if [ "${#missing[@]}" -gt 0 ]; then
    say "WARNING: environment variables not set: ${missing[*]} (set them in the claude.ai environment dialog)"
  fi
}

# Idempotent fast path: steps.sh unchanged + verify OK means exit right away
if [ -f "$STAMP_FILE" ] && [ "$(cat "$STAMP_FILE")" = "$(steps_hash)" ] \
   && verify >>"$LOG_FILE" 2>&1; then
  say "OK (cached)"
  check_env_vars
  exit 0
fi

say "running session-layer setup (light_steps)"
light_steps >>"$LOG_FILE" 2>&1 || say "ERROR: light_steps failed. Log: $LOG_FILE"
if verify >>"$LOG_FILE" 2>&1; then
  steps_hash >"$STAMP_FILE"
  say "OK"
else
  say "WARNING: verify failed. The environment layer may be missing an install — check that the content of scripts/remote-setup/environment-setup.sh is pasted into the Setup script in the claude.ai environment dialog (re-pasting rebuilds the environment cache). Log: $LOG_FILE"
fi
check_env_vars
# The hook never blocks the session: failures are only reported to the context as WARNINGs
exit 0
